let state=loadCurrent();
let activeView='sheet';
let inventoryTab='all';
let spellFilter='all';
let selectedItemId=null;
let dragState=null;

function normalize(raw){
  const base=clone(DEMO), out={...base,...clone(raw||{})};
  out.version=APP_VERSION;out.hp={...base.hp,...(raw?.hp||{})};out.abilities={...base.abilities,...(raw?.abilities||{})};out.passives={...base.passives,...(raw?.passives||{})};out.slotMax={...base.slotMax,...(raw?.slotMax||{})};out.slotUsed={...base.slotUsed,...(raw?.slotUsed||{})};out.money={...base.money,...(raw?.money||{})};
  out.skills=Array.isArray(raw?.skills)?raw.skills:base.skills;out.features=Array.isArray(raw?.features)?raw.features:base.features;out.tales=Array.isArray(raw?.tales)?raw.tales:base.tales;out.spells=Array.isArray(raw?.spells)?raw.spells:base.spells;out.items=Array.isArray(raw?.items)?raw.items:base.items;out.resources=Array.isArray(raw?.resources)?raw.resources:base.resources;out.journal=Array.isArray(raw?.journal)?raw.journal:base.journal;
  return out;
}
function loadCurrent(){try{return normalize(JSON.parse(localStorage.getItem(STORAGE_KEY)))}catch{return clone(DEMO)}}
function persist(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));renderHeader();renderHome()}
function getSlots(){try{const x=JSON.parse(localStorage.getItem(SLOTS_KEY));return Array.isArray(x)?x:[]}catch{return []}}
function setSlots(x){localStorage.setItem(SLOTS_KEY,JSON.stringify(x))}
function saveCurrentSlot(name=null){let list=getSlots(),id=state.saveSlotId,clean=(name||state.name||'Personnage').trim();if(id){const i=list.findIndex(x=>x.id===id);if(i>=0){list[i]={...list[i],name:clean,updatedAt:nowStamp(),state:clone(state)};setSlots(list);renderHome();return}}if(list.length>=MAX_CHARACTERS)return toast('20 personnages maximum');id=uid('char');state.saveSlotId=id;list.push({id,name:clean,updatedAt:nowStamp(),state:clone(state)});setSlots(list);persist();renderHome();toast('Personnage sauvegardé')}
function loadSlot(id){const slot=getSlots().find(x=>x.id===id);if(!slot)return;state=normalize(clone(slot.state));state.saveSlotId=id;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));closeHome();renderAll();toast(`Personnage chargé : ${state.name}`)}
function deleteSlot(id){if(!confirm('Supprimer ce personnage sauvegardé ?'))return;let list=getSlots().filter(x=>x.id!==id);setSlots(list);if(state.saveSlotId===id){state.saveSlotId=null;persist()}renderHome()}

function renderHeader(){
  $('#activeCharacterName').textContent=state.name;$('#activeCharacterMeta').textContent=`${state.species} · ${state.className} ${state.level} · ${state.subclass}`;$('#resumeName').textContent=state.name;document.documentElement.style.setProperty('--attune',state.attuneColor||'#c69a55');
}
function switchView(view){activeView=view;for(const v of ['sheet','features','spells','inventory','journal','illustrations'])$(`#${v}View`).classList.toggle('hidden',v!==view);$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));renderView(view)}
function renderView(view){if(view==='sheet')renderSheet();if(view==='features')renderFeatures();if(view==='spells')renderSpells();if(view==='inventory')renderInventory();if(view==='journal')renderJournal();if(view==='illustrations')renderIllustrations()}
function renderAll(){renderHeader();renderView(activeView);renderHome()}

function signed(n){return Number(n)>=0?`+${n}`:`${n}`}
function renderSheet(){
  const skills=state.skills.map(([name,bonus,status])=>`<div class="skill-row"><span><strong>${esc(name)}</strong><small>${esc(status)}</small></span><b>${signed(bonus)}</b></div>`).join('');
  const abilities=Object.entries(state.abilities).map(([k,v])=>`<div class="stat-card"><span>${k}</span><b>${v.score}</b><em>${signed(v.mod)} · JdS ${signed(v.save)}</em></div>`).join('');
  const resources=state.resources.map(r=>`<div class="resource-card"><div class="resource-card-head"><span><strong>${esc(r.name)}</strong><small>${esc(r.recharge)}</small></span><small>${r.max-r.used}/${r.max}</small></div><div class="resource-dots">${Array.from({length:r.max},(_,i)=>`<button class="resource-dot ${i<r.used?'used':''}" data-resource="${r.id}" data-index="${i}" title="Basculer"></button>`).join('')}</div></div>`).join('');
  $('#sheetView').innerHTML=`<div class="sheet-layout">
    <section class="panel profile-card">
      <div class="profile-top"><img src="${esc(state.portrait||'wonq-demo.png')}" alt="Portrait de ${esc(state.name)}"><div><span class="eyebrow">${esc(state.subtitle)}</span><h1>${esc(state.name)}</h1><p>${esc(state.species)} · ${esc(state.className)} ${state.level}<br>${esc(state.subclass)} · ${esc(state.background)}<br>${esc(state.guild)}</p><span class="tag">${esc(state.motto)}</span></div></div>
      <div class="vital-grid"><div class="vital"><b>${state.hp.current}/${state.hp.max}</b><span>PV</span></div><div class="vital"><b>${state.ac}</b><span>CA</span></div><div class="vital"><b>${signed(state.initiative)}</b><span>Initiative</span></div><div class="vital"><b>${state.speed}</b><span>Vitesse</span></div><div class="vital"><b>${state.spellDC}</b><span>DD sorts</span></div><div class="vital"><b>${signed(state.spellAttack)}</b><span>Attaque magique</span></div></div>
      <div class="hp-line"><label>PV actuels<div class="inline-number"><button class="ghost" data-hp="-1">−</button><input id="hpCurrent" type="number" min="0" max="${state.hp.max}" value="${state.hp.current}"><button class="ghost" data-hp="1">+</button></div></label><label>PV temporaires<input id="hpTemp" type="number" min="0" value="${state.hp.temp}"></label></div>
      <div class="stat-grid">${abilities}</div>
      <div><span class="eyebrow">VALEURS PASSIVES</span><p class="muted">Perception ${state.passives.Perception} · Intuition ${state.passives.Intuition} · Investigation ${state.passives.Investigation}</p></div>
      <div><span class="eyebrow">LANGUES</span><p class="muted">${state.languages.map(esc).join(' · ')}</p></div>
    </section>
    <div class="sheet-main">
      <section class="panel"><div class="panel-head"><div><span class="eyebrow">COMPÉTENCES</span><h2>Aptitudes pratiques</h2></div></div><div class="panel-body skill-grid">${skills}</div></section>
      <section class="panel"><div class="panel-head"><div><span class="eyebrow">ATTAQUES</span><h2>Options principales</h2></div></div><div class="panel-body attack-list">${state.attacks.map(a=>`<div class="attack-row"><strong>${esc(a.name)}</strong><b>${esc(a.attack)}</b><span>${esc(a.effect)}</span></div>`).join('')}</div></section>
      <section class="panel"><div class="panel-head"><div><span class="eyebrow">RESSOURCES</span><h2>Suivi rapide</h2></div><div><button id="btnShortRest" class="ghost">Repos court</button> <button id="btnLongRest" class="primary">Repos long</button></div></div><div class="panel-body resource-grid">${resources}</div></section>
    </div></div>`;
  $$('[data-resource]').forEach(b=>b.onclick=()=>{const r=state.resources.find(x=>x.id===b.dataset.resource);if(!r)return;const i=Number(b.dataset.index);r.used=(i<r.used)?i:i+1;persist();renderSheet()});
  $$('[data-hp]').forEach(b=>b.onclick=()=>{state.hp.current=Math.max(0,Math.min(state.hp.max,state.hp.current+Number(b.dataset.hp)));persist();renderSheet()});
  $('#hpCurrent').onchange=e=>{state.hp.current=Math.max(0,Math.min(state.hp.max,Number(e.target.value)||0));persist();renderSheet()};$('#hpTemp').onchange=e=>{state.hp.temp=Math.max(0,Number(e.target.value)||0);persist()};
  $('#btnShortRest').onclick=()=>{state.resources.forEach(r=>{if(r.recharge.includes('court'))r.used=0});persist();renderSheet();toast('Ressources de repos court récupérées')};
  $('#btnLongRest').onclick=()=>{state.hp.current=state.hp.max;state.hp.temp=0;Object.keys(state.slotUsed).forEach(k=>state.slotUsed[k]=0);state.resources.forEach(r=>{if(r.recharge.includes('Repos'))r.used=0});persist();renderSheet();toast('Repos long appliqué')};
}

function renderFeatures(){
  const groups=[...new Set(state.features.map(f=>f.group))];
  $('#featuresView').innerHTML=`<div class="feature-layout">${groups.map(group=>`<section class="panel"><div class="panel-head"><div><span class="eyebrow">APTITUDES</span><h2>${esc(group)}</h2></div></div><div class="panel-body">${state.features.filter(f=>f.group===group).map((f,i)=>`<details class="feature-card" ${i===0?'open':''}><summary><strong>${esc(f.name)}</strong><span>${esc(f.subtitle||'')}</span></summary><div class="feature-content"><p>${esc(f.text)}</p></div></details>`).join('')}</div></section>`).join('')}<section class="panel" style="grid-column:1/-1"><div class="panel-head"><div><span class="eyebrow">COLLÈGE DES ESPRITS</span><h2>Contes de l’Au-delà · d8</h2></div></div><div class="panel-body tales-grid">${state.tales.map(t=>`<div class="tale"><b>${t[0]} · ${esc(t[1])}</b><p>${esc(t[2])}</p></div>`).join('')}</div></section></div>`;
}

function slotHtml(){return Object.entries(state.slotMax).map(([lvl,max])=>`<div class="slot-level"><div class="slot-level-head"><strong>Niveau ${lvl}</strong><span>${max-state.slotUsed[lvl]}/${max}</span></div><div class="slot-dots">${Array.from({length:max},(_,i)=>`<button class="slot-dot ${i<state.slotUsed[lvl]?'used':''}" data-slot-level="${lvl}" data-slot-index="${i}"></button>`).join('')}</div></div>`).join('')}
function renderSpells(){
  const q=($('#spellSearch')?.value||'').toLowerCase();
  let spells=state.spells.filter(s=>(spellFilter==='all'||String(s.level)===String(spellFilter))&&(!q||`${s.name} ${s.school} ${s.text}`.toLowerCase().includes(q)));
  $('#spellsView').innerHTML=`<div class="spells-shell"><section class="panel slots-panel"><div class="section-head"><div><span class="eyebrow">EMPLACEMENTS</span><h2>Ressources magiques</h2></div><button id="btnRecoverSlots" class="ghost">Tout récupérer</button></div><div class="slot-tracker">${slotHtml()}</div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">SORTS CONNUS</span><h2>${state.spells.length} sorts et tours</h2></div></div><div class="panel-body spell-toolbar"><input id="spellSearch" placeholder="Rechercher un sort…" value="${esc(q)}"><button class="ghost filter-btn ${spellFilter==='all'?'active':''}" data-spell-filter="all">Tous</button><button class="ghost filter-btn ${spellFilter===0?'active':''}" data-spell-filter="0">Tours</button>${[1,2,3,4].map(n=>`<button class="ghost filter-btn ${String(spellFilter)===String(n)?'active':''}" data-spell-filter="${n}">Niv. ${n}</button>`).join('')}</div></section><div class="spell-list">${spells.map(s=>`<details class="spell-card"><summary><div><div class="spell-name">${esc(s.name)}</div><div class="spell-meta"><span class="tag">${s.level===0?'Tour de magie':`Niveau ${s.level}`}</span>${s.tags.map(t=>`<span class="tag ${t==='Concentration'?'concentration':''}">${esc(t)}</span>`).join('')}</div></div><div class="spell-school">${esc(s.school)}</div></summary><div class="spell-body"><div class="spell-facts"><div class="spell-fact"><span>Incantation</span><b>${esc(s.casting)}</b></div><div class="spell-fact"><span>Portée</span><b>${esc(s.range)}</b></div><div class="spell-fact"><span>Composantes</span><b>${esc(s.components)}</b></div><div class="spell-fact"><span>Durée</span><b>${esc(s.duration)}</b></div></div><p>${esc(s.text)}</p></div></details>`).join('')}</div></div>`;
  $$('[data-slot-level]').forEach(b=>b.onclick=()=>{const l=b.dataset.slotLevel,i=Number(b.dataset.slotIndex),used=state.slotUsed[l];state.slotUsed[l]=(i<used)?i:i+1;persist();renderSpells()});
  $('#btnRecoverSlots').onclick=()=>{Object.keys(state.slotUsed).forEach(k=>state.slotUsed[k]=0);persist();renderSpells()};
  $$('[data-spell-filter]').forEach(b=>b.onclick=()=>{spellFilter=b.dataset.spellFilter==='all'?'all':Number(b.dataset.spellFilter);renderSpells()});
  $('#spellSearch').oninput=e=>{const val=e.target.value;const list=$('.spell-list');const matches=state.spells.filter(s=>(spellFilter==='all'||String(s.level)===String(spellFilter))&&`${s.name} ${s.school} ${s.text}`.toLowerCase().includes(val.toLowerCase()));list.innerHTML=matches.map(s=>`<details class="spell-card"><summary><div><div class="spell-name">${esc(s.name)}</div><div class="spell-meta"><span class="tag">${s.level===0?'Tour de magie':`Niveau ${s.level}`}</span>${s.tags.map(t=>`<span class="tag ${t==='Concentration'?'concentration':''}">${esc(t)}</span>`).join('')}</div></div><div class="spell-school">${esc(s.school)}</div></summary><div class="spell-body"><div class="spell-facts"><div class="spell-fact"><span>Incantation</span><b>${esc(s.casting)}</b></div><div class="spell-fact"><span>Portée</span><b>${esc(s.range)}</b></div><div class="spell-fact"><span>Composantes</span><b>${esc(s.components)}</b></div><div class="spell-fact"><span>Durée</span><b>${esc(s.duration)}</b></div></div><p>${esc(s.text)}</p></div></details>`).join('')};
}

function itemIcon(item){return `${item.type||'divers'}.png`}
function itemCard(item){return `<div class="item-card ${item.magical?'magic':''} ${item.attuned?'attuned':''}" data-item-id="${item.id}"><span class="qty-badge">${item.qty||1}</span><button class="item-icon-wrap" data-item-icon="${item.id}" aria-label="${esc(item.name)}"><img src="${itemIcon(item)}" alt=""></button><strong>${esc(item.name)}</strong><small>${esc(item.rarity||ITEM_TYPES[item.type]||'')}</small></div>`}
function matchesInventory(item){if(inventoryTab==='all')return !item.equipped;if(inventoryTab==='equipped')return item.equipped;if(inventoryTab==='magic')return item.magical&&!item.equipped;if(inventoryTab==='weapons')return /arme_|baton_magique/.test(item.type)&&!item.equipped;if(inventoryTab==='armor')return /(armure|bouclier)/.test(item.type)&&!item.equipped;if(inventoryTab==='objects')return ['objet_merveilleux','anneau','baguette_magique','sceptre_magique','parchemin','potion'].includes(item.type)&&!item.equipped;return !item.equipped}
function renderMoney(){return `<div class="money-bar">${[['pp','PP'],['gp','PO'],['sp','PA'],['cp','PC']].map(([k,l])=>`<label class="coin"><span>${l}</span><input data-money="${k}" type="number" min="0" value="${state.money[k]||0}"></label>`).join('')}</div>`}
function renderInventory(){
  const filtered=state.items.filter(matchesInventory);
  const attuned=state.items.filter(i=>i.equipped&&i.attuned),equipped=state.items.filter(i=>i.equipped&&!i.attuned);
  const tabs=[['all','Sac'],['equipped','Équipés'],['magic','Magiques'],['weapons','Armes'],['armor','Armures'],['objects','Objets']];
  const body=inventoryTab==='equipped'?`<div class="equipment-layout"><section class="panel character-equipment"><div class="section-head attuned-label"><div><span class="eyebrow">APPARENCE</span><h2>${esc(state.name)}</h2></div><button id="btnEquipmentSettings" class="ghost">${icon('crayon')} Modifier</button></div><div class="equipment-portrait"><img src="${esc(state.portrait||'wonq-demo.png')}" alt="Portrait"></div><div class="attuned-label"><span class="eyebrow">OBJETS LIÉS · ${attuned.length}/3</span></div><div class="attuned-row equipment-dropzone" data-drop-equipment="true">${attuned.map(itemCard).join('')||'<div class="muted">Glisse ici les objets liés.</div>'}</div></section><section class="equipment-side"><div class="panel"><div class="panel-head"><div><span class="eyebrow">ÉQUIPÉ</span><h2>Objets portés ou prêts</h2></div></div><div class="panel-body inventory-grid equipment-dropzone" data-drop-equipment="true">${equipped.map(itemCard).join('')||'<div class="muted">Glisse ici un objet du sac.</div>'}</div></div><div class="panel"><div class="panel-head"><div><span class="eyebrow">SAC</span><h2>Disponible à déplacer</h2></div></div><div class="panel-body inventory-grid inventory-dropzone" data-drop-inventory="true">${state.items.filter(i=>!i.equipped).map(itemCard).join('')}</div></div></section></div>`:`<section class="panel"><div class="panel-head"><div><span class="eyebrow">CONTENU</span><h2>${filtered.length} objet${filtered.length>1?'s':''}</h2></div></div><div class="panel-body inventory-grid inventory-dropzone" data-drop-inventory="true">${filtered.map(itemCard).join('')||'<div class="muted">Aucun objet dans cette vue.</div>'}</div></section>`;
  $('#inventoryView').innerHTML=`<div class="inventory-shell"><section class="panel"><div class="panel-head inventory-toolbar"><div><span class="eyebrow">INVENTAIRE</span><h2>Équipement et possessions</h2></div><div class="inventory-actions"><button id="btnAddItem" class="primary">${icon('plus')} Ajouter</button><button id="btnImportItem" class="violet">${icon('fleche_bas')} Importer</button>${renderMoney()}</div></div><div class="panel-body inventory-tabs">${tabs.map(([id,label])=>`<button class="ghost inventory-tab ${inventoryTab===id?'active':''}" data-inventory-tab="${id}">${label}</button>`).join('')}</div></section>${body}</div>`;
  $$('[data-inventory-tab]').forEach(b=>b.onclick=()=>{inventoryTab=b.dataset.inventoryTab;hideItemPopover();renderInventory()});$('#btnAddItem').onclick=()=>openItemEditor();$('#btnImportItem').onclick=()=>$('#itemImportFile').click();
  $$('[data-money]').forEach(i=>i.onchange=()=>{state.money[i.dataset.money]=Math.max(0,Number(i.value)||0);persist()});if($('#btnEquipmentSettings'))$('#btnEquipmentSettings').onclick=openEquipmentSettings;
  bindItemInteractions();
}

function bindItemInteractions(){
  $$('[data-item-icon]').forEach(el=>{
    let start=null,ghost=null,moved=false;
    el.onpointerdown=e=>{if(e.button!==undefined&&e.button!==0)return;start={x:e.clientX,y:e.clientY,id:el.dataset.itemIcon,pointerId:e.pointerId};moved=false;try{el.setPointerCapture(e.pointerId)}catch{}};
    el.onpointermove=e=>{if(!start||e.pointerId!==start.pointerId)return;const d=Math.hypot(e.clientX-start.x,e.clientY-start.y);if(d<9&&!moved)return;if(!moved){moved=true;ghost=document.createElement('div');ghost.className='drag-ghost';const item=state.items.find(i=>i.id===start.id);ghost.innerHTML=`<img src="${itemIcon(item)}" alt="">`;document.body.appendChild(ghost);el.closest('.item-card')?.classList.add('dragging')}ghost.style.left=`${e.clientX}px`;ghost.style.top=`${e.clientY}px`;$$('.drop-active').forEach(x=>x.classList.remove('drop-active'));const target=document.elementFromPoint(e.clientX,e.clientY);target?.closest('[data-drop-equipment],[data-drop-inventory],.item-card')?.classList.add('drop-active')};
    el.onpointerup=e=>{if(!start)return;const item=state.items.find(i=>i.id===start.id);if(moved){const target=document.elementFromPoint(e.clientX,e.clientY),equip=target?.closest('[data-drop-equipment]'),inv=target?.closest('[data-drop-inventory]'),card=target?.closest('.item-card');if(equip)item.equipped=true;else if(inv)item.equipped=false;if(card&&card.dataset.itemId!==item.id)reorderItem(item.id,card.dataset.itemId);persist();hideItemPopover();renderInventory()}else showItemPopover(item,el);ghost?.remove();$$('.dragging,.drop-active').forEach(x=>x.classList.remove('dragging','drop-active'));start=null};
    el.onpointercancel=()=>{ghost?.remove();start=null;$$('.dragging,.drop-active').forEach(x=>x.classList.remove('dragging','drop-active'))};
  });
}
function reorderItem(id,beforeId){const from=state.items.findIndex(i=>i.id===id),to=state.items.findIndex(i=>i.id===beforeId);if(from<0||to<0)return;const [x]=state.items.splice(from,1);const newTo=state.items.findIndex(i=>i.id===beforeId);state.items.splice(newTo,0,x)}
function showItemPopover(item,anchor){if(!item)return;selectedItemId=item.id;const pop=$('#itemPopover');pop.innerHTML=`<div class="popover-head"><div><span class="eyebrow">${esc(ITEM_TYPES[item.type]||'OBJET')}</span><h3>${esc(item.name)}</h3></div><button class="icon-button small" id="btnClosePopover"><img src="fermer.png" alt=""></button></div><div class="spell-meta"><span class="tag">${esc(item.rarity||'Sans rareté')}</span>${item.magical?'<span class="tag magic">Magique</span>':''}${item.attuned?'<span class="tag magic">Lié</span>':''}${item.equipped?'<span class="tag">Équipé</span>':''}</div><div class="popover-body"><p><strong>${esc(item.summary||'')}</strong></p><p>${esc(item.description||'Aucune description.')}</p>${item.weight?`<p>Poids : ${esc(item.weight)}</p>`:''}</div><div class="popover-actions"><button id="btnExportThisItem" class="violet">${icon('fleche_haut')} Exporter</button><button id="btnEditThisItem" class="ghost">${icon('crayon')} Modifier</button></div>`;pop.classList.remove('hidden');pop.setAttribute('aria-hidden','false');const rect=anchor.getBoundingClientRect(),w=Math.min(420,window.innerWidth-24);pop.style.width=`${w}px`;let left=Math.max(12,Math.min(window.innerWidth-w-12,rect.left+rect.width/2-w/2));pop.style.left=`${left}px`;const estimated=Math.min(pop.scrollHeight||260,window.innerHeight*.52);let top=rect.bottom+8;if(top+estimated>window.innerHeight-80)top=Math.max(10,rect.top-estimated-8);pop.style.top=`${top}px`;$('#btnClosePopover').onclick=hideItemPopover;$('#btnEditThisItem').onclick=()=>{hideItemPopover();openItemEditor(item.id)};$('#btnExportThisItem').onclick=()=>exportItem(item)}
function hideItemPopover(){const p=$('#itemPopover');p.classList.add('hidden');p.setAttribute('aria-hidden','true');selectedItemId=null}
function openItemEditor(id=null){const item=id?state.items.find(i=>i.id===id):null,f=$('#itemEditorForm');f.reset();$('#itemEditorTitle').textContent=item?'Modifier l’objet':'Nouvel objet';f.elements.id.value=item?.id||'';for(const k of ['name','type','rarity','qty','weight','summary','description'])if(f.elements[k])f.elements[k].value=item?.[k]??(k==='qty'?1:'');for(const k of ['magical','attuned','equipped'])f.elements[k].checked=!!item?.[k];$('#btnDeleteItem').style.visibility=item?'visible':'hidden';$('#itemEditorDialog').showModal()}
function saveItemFromForm(f){const data=Object.fromEntries(new FormData(f));const id=data.id||uid('itm'),existing=state.items.find(i=>i.id===id);const obj={id,name:String(data.name||'Objet').trim(),type:data.type||'divers',rarity:String(data.rarity||'').trim(),qty:Math.max(1,Number(data.qty)||1),weight:String(data.weight||'').trim(),summary:String(data.summary||'').trim(),description:String(data.description||'').trim(),magical:f.elements.magical.checked,attuned:f.elements.attuned.checked,equipped:f.elements.equipped.checked};if(existing)Object.assign(existing,obj);else state.items.push(obj);persist();renderInventory();$('#itemEditorDialog').close()}
function exportItem(item){downloadJson(`Cockpit-Objet-${safeFileName(item.name)}.json`,{format:'cockpit-player-item',version:1,item:clone(item)})}
function openEquipmentSettings(){const f=$('#equipmentSettingsForm');f.elements.attuneColor.value=state.attuneColor||'#c69a55';$('#equipmentSettingsDialog').showModal()}

function renderJournal(){const rows=[...state.journal].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))).map(j=>`<article class="journal-entry"><div><span class="eyebrow">${esc(j.type)}</span><h3>${esc(j.title||'Note')}</h3><p>${esc(j.text)}</p><small>${new Date(j.createdAt).toLocaleString('fr-FR')}</small></div><div class="journal-entry-actions"><button class="ghost" data-edit-note="${j.id}">${icon('crayon')}</button><button class="danger" data-delete-note="${j.id}">${icon('fermer')}</button></div></article>`).join('')||'<div class="muted">Aucune note.</div>';$('#journalView').innerHTML=`<div class="journal-shell"><section class="panel"><div class="panel-head"><div><span class="eyebrow">NOTES PERSONNELLES</span><h2>Journal de ${esc(state.name)}</h2></div><div class="journal-toolbar"><button id="btnAddNote" class="primary">${icon('plus')} Note</button><button id="btnExportJournal" class="violet">${icon('fleche_haut')} Exporter</button></div></div></section><div class="journal-list">${rows}</div></div>`;$('#btnAddNote').onclick=()=>{const f=$('#noteEditorForm');f.reset();delete f.dataset.editId;$('#noteEditorDialog').showModal()};$('#btnExportJournal').onclick=exportJournal;$$('[data-edit-note]').forEach(b=>b.onclick=()=>{const j=state.journal.find(x=>x.id===b.dataset.editNote),f=$('#noteEditorForm');if(!j)return;f.elements.type.value=j.type;f.elements.title.value=j.title||'';f.elements.text.value=j.text;f.dataset.editId=j.id;$('#noteEditorDialog').showModal()});$$('[data-delete-note]').forEach(b=>b.onclick=()=>{if(!confirm('Supprimer cette note ?'))return;state.journal=state.journal.filter(x=>x.id!==b.dataset.deleteNote);persist();renderJournal()})}
function exportJournal(){const lines=[`Journal — ${state.name}`,'',...state.journal.slice().sort((a,b)=>String(a.createdAt).localeCompare(String(b.createdAt))).map((j,i)=>`${i+1}. [${new Date(j.createdAt).toLocaleString('fr-FR')}] ${j.title||j.type}\n${j.text}\n`)];downloadBlob(`Journal-${safeFileName(state.name)}-${new Date().toISOString().slice(0,10)}.txt`,new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}))}

/* Illustrations locales : même logique que Cockpit MJ, hors export personnage. */
const ILLUSTRATION_DB='cockpit-player-illustrations-v1', ILLUSTRATION_STORE='images', META_STORE='meta';let illustrationDbPromise=null,illustrationRecords=[],illustrationSelected=new Set(),illustrationUrls=[],illustrationMove=false,pendingIllustrations=[];let illustrationCategories=[['people','Personnages'],['places','Lieux'],['items','Objets'],['clues','Indices'],['misc','Divers']];
function openIllustrationDb(){if(illustrationDbPromise)return illustrationDbPromise;illustrationDbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open(ILLUSTRATION_DB,1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(ILLUSTRATION_STORE))db.createObjectStore(ILLUSTRATION_STORE,{keyPath:'id'});if(!db.objectStoreNames.contains(META_STORE))db.createObjectStore(META_STORE,{keyPath:'key'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return illustrationDbPromise}
async function idbAll(){const db=await openIllustrationDb();return new Promise((res,rej)=>{const tx=db.transaction(ILLUSTRATION_STORE,'readonly'),r=tx.objectStore(ILLUSTRATION_STORE).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
async function idbPut(records){const db=await openIllustrationDb();return new Promise((res,rej)=>{const tx=db.transaction(ILLUSTRATION_STORE,'readwrite'),st=tx.objectStore(ILLUSTRATION_STORE);records.forEach(x=>st.put(x));tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
async function idbDelete(ids){const db=await openIllustrationDb();return new Promise((res,rej)=>{const tx=db.transaction(ILLUSTRATION_STORE,'readwrite'),st=tx.objectStore(ILLUSTRATION_STORE);ids.forEach(x=>st.delete(x));tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
async function loadIllustrationCats(){const db=await openIllustrationDb();return new Promise((res,rej)=>{const tx=db.transaction(META_STORE,'readonly'),r=tx.objectStore(META_STORE).get('cats');r.onsuccess=()=>res(r.result?.value||[]);r.onerror=()=>rej(r.error)})}
async function saveIllustrationCats(custom){const db=await openIllustrationDb();return new Promise((res,rej)=>{const tx=db.transaction(META_STORE,'readwrite');tx.objectStore(META_STORE).put({key:'cats',value:custom});tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
function cleanupIllustrationUrls(){illustrationUrls.forEach(URL.revokeObjectURL);illustrationUrls=[]}
async function renderIllustrations(){const custom=await loadIllustrationCats();illustrationCategories=[['people','Personnages'],['places','Lieux'],['items','Objets'],['clues','Indices'],['misc','Divers'],...custom];illustrationRecords=(await idbAll()).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));cleanupIllustrationUrls();const content=illustrationCategories.map(([id,label])=>{const arr=illustrationRecords.filter(x=>(x.category||'misc')===id);return `<details class="illustration-drawer" ${arr.length?'open':''}><summary data-illustration-category="${id}"><strong>${esc(label)} <span class="counter-pill">${arr.length}</span></strong><span class="muted">${arr.filter(x=>x.sentAt).length?`${arr.filter(x=>x.sentAt).length} envoyée(s)`:''}</span></summary><div class="illustration-grid">${arr.map(x=>{const url=URL.createObjectURL(x.blob);illustrationUrls.push(url);return `<button class="illustration-card ${illustrationSelected.has(x.id)?'selected':''} ${illustrationMove&&illustrationSelected.has(x.id)?'moving':''} ${x.sentAt?'sent':''}" data-illustration-id="${x.id}"><img src="${url}" alt="${esc(x.name)}"><footer>${esc(x.name)}</footer></button>`}).join('')||'<div class="illustration-empty">Aucune illustration.</div>'}</div></details>`}).join('');$('#illustrationsView').innerHTML=`<div class="illustrations-shell panel illustrations-panel"><div class="panel-head"><div><span class="eyebrow">BIBLIOTHÈQUE LOCALE</span><h2>Illustrations</h2></div><div class="illustrations-head-actions"><span id="illustrationMeta" class="illustration-meta">${illustrationSelected.size?`${illustrationSelected.size} sélectionnée(s)`:'Aucune sélection'}</span><button id="btnDeleteIllustrations" class="danger" ${illustrationSelected.size?'':'disabled'}>Supprimer</button><button id="btnAddIllustrationCategory" class="blue">+ Catégorie</button><button id="btnMoveIllustrations" class="green" ${illustrationSelected.size?'':'disabled'}>${illustrationMove?'Annuler déplacement':'Déplacer'}</button><button id="btnImportIllustrations" class="violet">${icon('fleche_bas')} Importer</button><button id="btnExportIllustrations" class="violet" ${illustrationSelected.size?'':'disabled'}>${icon('fleche_haut')} Exporter</button></div></div><div class="illustrations-content">${content}</div></div>`;$$('[data-illustration-id]').forEach(b=>b.onclick=()=>{const id=b.dataset.illustrationId;illustrationSelected.has(id)?illustrationSelected.delete(id):illustrationSelected.add(id);renderIllustrations()});$$('[data-illustration-category]').forEach(s=>s.onclick=e=>{if(!illustrationMove)return;e.preventDefault();moveIllustrationsTo(s.dataset.illustrationCategory)});$('#btnImportIllustrations').onclick=()=>$('#illustrationImportFile').click();$('#btnAddIllustrationCategory').onclick=()=>$('#illustrationCategoryDialog').showModal();$('#btnMoveIllustrations').onclick=()=>{illustrationMove=!illustrationMove;renderIllustrations()};$('#btnDeleteIllustrations').onclick=()=>{const n=illustrationSelected.size;$('#illustrationDeleteMessage').textContent=`Supprimer ${n} illustration${n>1?'s':''} de cet appareil ?`;$('#illustrationDeleteDialog').showModal()};$('#btnExportIllustrations').onclick=shareIllustrations}
async function moveIllustrationsTo(cat){const selected=illustrationRecords.filter(x=>illustrationSelected.has(x.id));selected.forEach(x=>x.category=cat);await idbPut(selected);illustrationSelected.clear();illustrationMove=false;renderIllustrations()}
async function shareIllustrations(){const selected=illustrationRecords.filter(x=>illustrationSelected.has(x.id));const files=selected.map(x=>new File([x.blob],x.name,{type:x.type||'image/jpeg'}));try{if(!navigator.share)throw new Error();if(navigator.canShare&&!navigator.canShare({files}))throw new Error();await navigator.share({title:`Cockpit Joueur · ${files.length} illustration(s)`,files});const stamp=nowStamp();selected.forEach(x=>x.sentAt=stamp);await idbPut(selected);illustrationSelected.clear();renderIllustrations()}catch(e){if(e?.name!=='AbortError')toast('Partage de fichiers indisponible sur cet appareil')}}

function renderHome(){const slots=getSlots();$('#characterSlotCount').textContent=`${slots.length} / ${MAX_CHARACTERS}`;$('#characterSlots').innerHTML=`<article class="character-slot"><div><span class="eyebrow">DÉMO INTÉGRÉE</span><strong>Wonq · Gardien des Absents</strong><small>Hadozee · Barde 8 · Collège des Esprits</small></div><div class="slot-actions"><button id="btnLoadDemo" class="primary">Charger</button></div></article>${slots.map(s=>`<article class="character-slot ${state.saveSlotId===s.id?'current':''}"><div><strong>${esc(s.name)}</strong><small>${new Date(s.updatedAt).toLocaleString('fr-FR')}</small></div><div class="slot-actions"><button class="primary" data-load-slot="${s.id}">Reprendre</button><button class="violet" data-export-slot="${s.id}">${icon('fleche_haut')} Exporter</button><button class="danger" data-delete-slot="${s.id}">×</button></div></article>`).join('')}`;$('#themeChoices').innerHTML=THEMES.map(t=>`<button class="theme-choice ${document.documentElement.dataset.theme===t.id?'active':''}" data-theme="${t.id}"><span class="theme-swatches">${t.sw.map(c=>`<i style="background:${c}"></i>`).join('')}</span><strong>${esc(t.name)}</strong></button>`).join('');$('#btnLoadDemo').onclick=()=>{state=clone(DEMO);state.saveSlotId=null;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));closeHome();renderAll()};$$('[data-load-slot]').forEach(b=>b.onclick=()=>loadSlot(b.dataset.loadSlot));$$('[data-delete-slot]').forEach(b=>b.onclick=()=>deleteSlot(b.dataset.deleteSlot));$$('[data-export-slot]').forEach(b=>b.onclick=()=>{const slot=slots.find(x=>x.id===b.dataset.exportSlot);if(slot)exportCharacter(slot.state)});$$('[data-theme]').forEach(b=>b.onclick=()=>setTheme(b.dataset.theme))}
function openHome(){renderHome();$('#homeOverlay').classList.add('show');$('#homeOverlay').setAttribute('aria-hidden','false')}
function closeHome(){$('#homeOverlay').classList.remove('show');$('#homeOverlay').setAttribute('aria-hidden','true')}
function setTheme(id){if(!THEMES.some(t=>t.id===id))return;document.documentElement.dataset.theme=id;localStorage.setItem(THEME_KEY,id);renderHome()}

function downloadBlob(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},800)}
function downloadJson(name,obj){downloadBlob(name,new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}))}
function exportCharacter(char=state){const out=clone(char);out.saveSlotId=null;downloadJson(`Cockpit-Joueur-${safeFileName(out.name)}.json`,{format:'cockpit-player-character',formatVersion:1,appVersion:APP_VERSION,exportedAt:nowStamp(),character:out})}
async function importCharacter(file){const raw=JSON.parse(await file.text()),char=normalize(raw.character||raw);let slots=getSlots();if(slots.length>=MAX_CHARACTERS)throw new Error('20 personnages maximum');const id=uid('char');char.saveSlotId=id;slots.push({id,name:char.name||file.name,updatedAt:nowStamp(),state:clone(char)});setSlots(slots);renderHome();toast(`Personnage importé : ${char.name}`)}

function openSearch(){const d=$('#searchDialog');d.showModal();const inp=$('#globalSearchInput');inp.value='';renderSearchResults('');setTimeout(()=>inp.focus(),30)}
function renderSearchResults(q){q=q.toLowerCase().trim();if(!q){$('#globalSearchResults').innerHTML='<div class="muted">Recherche dans les sorts, aptitudes, objets et notes.</div>';return}const res=[];state.spells.forEach(x=>{if(`${x.name} ${x.text}`.toLowerCase().includes(q))res.push({view:'spells',title:x.name,sub:'Sort'})});state.features.forEach(x=>{if(`${x.name} ${x.text}`.toLowerCase().includes(q))res.push({view:'features',title:x.name,sub:x.group})});state.items.forEach(x=>{if(`${x.name} ${x.summary} ${x.description}`.toLowerCase().includes(q))res.push({view:'inventory',title:x.name,sub:'Inventaire'})});state.journal.forEach(x=>{if(`${x.title} ${x.text}`.toLowerCase().includes(q))res.push({view:'journal',title:x.title||'Note',sub:'Journal'})});$('#globalSearchResults').innerHTML=res.slice(0,40).map(r=>`<button class="search-result" data-search-view="${r.view}"><strong>${esc(r.title)}</strong><small>${esc(r.sub)}</small></button>`).join('')||'<div class="muted">Aucun résultat.</div>';$$('[data-search-view]').forEach(b=>b.onclick=()=>{$('#searchDialog').close();switchView(b.dataset.searchView)})}
function toast(text){let t=$('#toast');if(!t){t=document.createElement('div');t.id='toast';t.style.cssText='position:fixed;z-index:999;left:50%;bottom:90px;transform:translateX(-50%);background:#1c1712;border:1px solid #7d623c;border-radius:9px;padding:9px 12px;font-size:9px;box-shadow:0 10px 30px rgba(0,0,0,.4)';document.body.appendChild(t)}t.textContent=text;t.style.display='block';clearTimeout(toast._t);toast._t=setTimeout(()=>t.style.display='none',2600)}

/* Events */
$$('.nav-btn').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$('#btnHome').onclick=openHome;$('#btnCloseHome').onclick=closeHome;$('#btnResume').onclick=closeHome;$('#btnGlobalSearch').onclick=openSearch;$('#globalSearchInput').oninput=e=>renderSearchResults(e.target.value);$$('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close)?.close());
$('#btnSaveCharacter').onclick=()=>saveCurrentSlot();$('#btnImportCharacter').onclick=()=>$('#characterImportFile').click();$('#characterImportFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{await importCharacter(f)}catch(err){toast(err.message||'Import incompatible')}e.target.value=''};
$('#itemTypeSelect').innerHTML=Object.entries(ITEM_TYPES).map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('');$('#itemEditorForm').onsubmit=e=>{e.preventDefault();saveItemFromForm(e.target)};$('#btnDeleteItem').onclick=()=>{const id=$('#itemEditorForm').elements.id.value;if(!id||!confirm('Supprimer cet objet ?'))return;state.items=state.items.filter(x=>x.id!==id);persist();$('#itemEditorDialog').close();renderInventory()};$('#itemImportFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const raw=JSON.parse(await f.text()),item=raw.item||raw;if(!item?.name)throw new Error();item.id=uid('itm');state.items.push(item);persist();renderInventory();toast('Objet importé')}catch{toast('Objet incompatible')}e.target.value=''};
$('#equipmentSettingsForm').onsubmit=e=>{e.preventDefault();state.attuneColor=e.target.elements.attuneColor.value||'#c69a55';persist();$('#equipmentSettingsDialog').close();renderInventory()};$('#btnImportPortrait').onclick=()=>$('#portraitImportFile').click();$('#portraitImportFile').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{state.portrait=r.result;persist();renderInventory()};r.readAsDataURL(f);e.target.value=''};$('#btnResetPortrait').onclick=()=>{state.portrait='wonq-demo.png';persist();renderInventory()};
$('#noteEditorForm').onsubmit=e=>{e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f)),id=f.dataset.editId;if(id){const j=state.journal.find(x=>x.id===id);Object.assign(j,{type:data.type,title:data.title,text:data.text})}else state.journal.push({id:uid('j'),type:data.type,title:data.title,text:data.text,createdAt:nowStamp()});delete f.dataset.editId;persist();$('#noteEditorDialog').close();renderJournal()};
$('#illustrationImportFile').onchange=e=>{pendingIllustrations=[...e.target.files].filter(f=>/^image\/(png|jpeg)$/.test(f.type));if(!pendingIllustrations.length)return;$('#illustrationImportRows').innerHTML=pendingIllustrations.map((f,i)=>`<div class="illustration-import-row"><span><strong>${esc(f.name)}</strong><small>${Math.round(f.size/1024)} Ko</small></span><select data-cat-index="${i}">${illustrationCategories.map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('')}</select></div>`).join('');$('#illustrationImportDialog').showModal();e.target.value=''};$('#illustrationImportForm').onsubmit=async e=>{e.preventDefault();const records=pendingIllustrations.map((f,i)=>({id:uid('img'),name:f.name,type:f.type,category:$(`[data-cat-index="${i}"]`).value,blob:f.slice(0,f.size,f.type),createdAt:nowStamp(),sentAt:null}));await idbPut(records);pendingIllustrations=[];$('#illustrationImportDialog').close();renderIllustrations()};$('#illustrationCategoryForm').onsubmit=async e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name)return;const custom=await loadIllustrationCats(),id=uid('cat');custom.push([id,name]);await saveIllustrationCats(custom);e.target.reset();$('#illustrationCategoryDialog').close();renderIllustrations()};$('#btnCancelIllustrationDelete').onclick=()=>$('#illustrationDeleteDialog').close();$('#btnConfirmIllustrationDelete').onclick=async()=>{await idbDelete([...illustrationSelected]);illustrationSelected.clear();illustrationMove=false;$('#illustrationDeleteDialog').close();renderIllustrations()};

document.addEventListener('pointerdown',e=>{if(!e.target.closest('#itemPopover')&&!e.target.closest('[data-item-icon]'))hideItemPopover()});
window.addEventListener('resize',hideItemPopover);
const savedTheme=localStorage.getItem(THEME_KEY)||'emerald';setTheme(savedTheme);renderAll();
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('service-worker.js?v=0.1.0').catch(()=>{}));
